function dir$sysuserinfo(p){
  this.constructor(p);
}
dir$sysuserinfo.prototype = new DirEvent();
dir$sysuserinfo.prototype.beforeInit = function(){
  var p = this._dir;
}
dir$sysuserinfo.prototype.afterInit = function(){
  var p = this._dir;

  p.jObject('vpassword').attr('type', 'password');
  p.jObject('vpassword2').attr('type', 'password');

  if(p.options.action == 'NEW'){
    p.valForm('vpassword', '');
    p.valForm('vpassword2', '');
  }else{
    p.valForm('vpassword', '*******' + String.fromCharCode(255));
    p.valForm('vpassword2', '*******' + String.fromCharCode(255));
  }

  //readonly field
  if(p.options._admin == 0){
    p.setDisabled('parent_username', true);
    p.setDisabled('rg_code', true);
    p.setDisabled('language', true);
    p.setDisabled('lock_yn', true);
	p.setDisabled('status', true);

  }
  	if(p.options.action != 'NEW')
	{
		p.setDisabled(['username','nickname'], true);

	}
  if (p.valForm('admin') == 1) p.setHidden('parent_username', true);

  if(p.options.action == 'EDIT') p.request('LoadUserName', '', ['username']);
}

dir$sysuserinfo.prototype.beforeButtonDialogClick = function(id){
  if (id == 'cancel') return true;
  var p = this._dir, l = ($.lan == 'v' ? 0 : 1);
  p.valForm('password', MD5(p.valForm('vpassword')));

  var hidden = '*******' + String.fromCharCode(255), message = [
  ['Mật khẩu vừa nhập không hợp lệ.', 'Your password is too simple. Please retype.'],
  ['Kiểm tra lại mật khẩu nhập không đúng.', 'Your password is invalid. Please retype.'],
  ['Mật khẩu tối thiểu phải từ 6 ký tự.', 'Password must consist of at least 6 characters.'],
  ['Mật khẩu tối thiểu phải từ 6 ký tự và phải có số và chữ', 'Password must consist of at least 6 characters in both numbers and letters.'],
  ['Mật khẩu tối thiểu phải từ 6 ký tự và phải có số, chữ, chữ hoa.', 'Password must consist of at least 6 characters in both numbers and letters with upper-case letter.'],
  ['Mật khẩu tối thiểu phải từ 6 ký tự và phải có số, chữ, chữ hoa, kí tự khác ngoài chữ và số.', 'Password must consist of at least 6 characters in both numbers and letters with upper-case letter and other characters except numbers and letters.']
  ], o2 = p.jObject('vpassword'), o3 = p.jObject('vpassword2'), o = $.trim(o2.val()), u = $.trim(o3.val()), v = (o != hidden), errorMessage = null;

  username = $.trim(p.jObject('username').val());
  var e = (($.lan == 'v') ? 'Trường <span class="Highlight">Thư (Email)</span> không hợp lệ.' : 'Invalid <span class="Highlight">Email</span>.');

  if(v) p.valForm('update_pass', '1');
  else p.valForm('update_pass', '0');

  if(o2.val() != o3.val()){
    $.alert(message[1][l], null, p, function(e){p.jObject('vpassword').focus(); e._close()});
    return false;
  }

  if (v) {
    var wordList = '111111,123456,654321,1234567,12345678,123456789,0123456789,1234567890,123123,abc123,password,passw0rd,iloveyou';

    if ((wordList.indexOf(u) > -1) || (u == username)) errorMessage = message[0][l];
    else{
      if (o != u) errorMessage = message[1][l];
      else {
        var type = 2;
        switch (type) {
          case 2:
            if (o.length < 6) errorMessage = message[2][l];
            break;
          case 3:
            if (!/^(?=.*\d)(?=.*[a-z]).{6,}/.test(o)) errorMessage = message[3][l];
            break;
          case 4:
            if (!/^(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/.test(o)) errorMessage = message[4][l];
            break;
          case 5:
            if (!/^(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*[\W]).{6,}/.test(o)) errorMessage = message[5][l];
            break;
          default:
            break;
        }
      }
    }
    if(errorMessage){
      $.alert(errorMessage, null, p, function(e){p.jObject('vpassword').focus(); e._close()});
      return false;
    }
  }

  if ($.trim(username).indexOf(' ', 0) >= 0 || username.indexOf('.', 0) >= 0) {
    var msg = ($.lan == 'v' ? 'Trường <span class="Highlight">Tên</span> không được phép có khoảng trắng hoặc chứa ký tự: <span class="Highlight">[.]</span>.' : 'Field <span class="Highlight">Name</span> cannot contain blank or any of the following character: <span class="Highlight">[.]</span>.');
    $.alert(msg, null, p, function(msg){p.jObject('username').focus(); msg._close()});
    return false;
  }

  if ((p.valForm('e_mail') != '') && (/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/.test(p.valForm('e_mail')) == false)) {
    $.alert(e, null, p, function(e){p.jObject('e_mail').focus(); e._close()});
    return false;
  }
  return true;
}







