if @action = 'NEW' and @@admin = 0 begin
  select N'$AdminAccess' as message
  return
end
select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table

declare @fscript nvarchar(4000)
if @action in ('EDIT', 'VIEW') exec ISWIFTStoreGetListFiles 'image_id', @user_id, 'SysUser', '', @fscript output
if @fscript is null set @fscript = ''
if @action = 'EDIT' begin
  if exists (select 1 from @@table a where a.user_id in (select parent_user from #@@table))
    select a.username as parent_username, a.nickname as parent_username_name, @fscript as script from @@table a where a.user_id in (select parent_user from #@@table)
  else
    select @fscript as script
end


drop table #@@table







declare @rk varchar(16), @admin bit
select @rk = lower(left(replace(newid(),'-',''),16))
update sysuserinfo set random_key = @rk where user_id = @@userId

select @admin = admin from @@table where user_id = @@userId
select 'p.options._key = ''' + @rk + '''; p.options._admin = ' + rtrim(@admin) as script







declare @ename varchar(64)
select @ename = username from @@table where user_id = @user_id
if @username <> @ename begin
  if exists(select 1 from @@table where username = @username and user_id <> @user_id) or exists(select 1 from sysgroupinfo where groupname = @username) begin
    select '' as field, '$exists' as message
    return
  end
end
if @parent_username <> '' and @admin = 1 begin
  select '$NotParent4Admin' as message, 'parent_username' as field
  return
end
if rtrim(@e_mail) <> '' and exists(select 1 from @@table where e_mail = @e_mail and user_id <> @user_id) begin
  select 'e_mail' as field, '$emailExists' as message
  return
end
if rtrim(@phone) <> '' and exists (select 1 from @@table where phone = @phone and user_id <> @user_id) begin
  select 'phone' as field, '$phoneExists' as message
  return
end
declare @res tinyint, @old_parent_username varchar(64)
select @old_parent_username = username from @@table where user_id in (select parent_user from @@table where user_id = @user_id)
select @old_parent_username = isnull(@old_parent_username, '')
exec ISWIFTStoredSystemUserRef @user_id, @parent_username, @old_parent_username, 'EDIT', @user_ref output, @res output

if @res = 0 begin
  select 'parent_user' as field, '$parentConflict' as message
  return
end

if @update_pass = 0 select @password = password from @@table where user_id = @user_id







update dmttin set status = 0 from dmttin where id0 = rtrim(@user_id) and xgroup = 'SysUser'
if @image_id <> '' update dmttin set status = 1, id0 = rtrim(@user_id) from dmttin where charindex(id, @image_id) > 0 and xgroup = 'SysUser'

if @update_pass = 0 update @@table set password = @password where user_id = @user_id
else exec dbo.ISWIFTStoreUpdatePasswordUser @username, @password

select @parent_user = isnull(max(user_id), 0) from @@table where username = @parent_username
update @@table set parent_user = @parent_user, datetime2 = getdate(), user_id2 = @@userId, image_id = @image_id where [%whereFieldKey]
if exists (select 1 from @@table where user_id = @@userId and admin = 1) begin
  if @lock_yn = 0
    update @@table set errorpass = 0 where user_id = @user_id
  else
    update @@table set errorpass = 99 where user_id = @user_id
end







if (select count(1) from sysuserinfo where status = 1) >= (select maxuser from sysinfo) begin
  select '' as field, '$maxUser' as message
  return
end

if exists(select 1 from @@table where username = @username) or exists(select 1 from sysgroupinfo where groupname = @username) begin
	select '' as field, replace('$exists', '%s', rtrim(@username)) as message
  return
end
if rtrim(@e_mail) <> '' and exists (select 1 from @@table where e_mail = @e_mail) begin
  select 'e_mail' as field, '$emailExists' as message
  return
end
if rtrim(@phone) <> '' and exists (select 1 from @@table where phone = @phone) begin
  select 'phone' as field, '$phoneExists' as message
  return
end
select @parent_user = user_id from @@table where username = @parent_username

declare @res tinyint
exec ISWIFTStoredSystemUserRef @user_id, @parent_username, '', 'NEW', @user_ref output, @res output

if @res = 0 begin
  select 'parent_user' as field, '$parentConflict' as message
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId
--select @user_id = max(user_id) + 1 from @@table
